use doorsm::{Door, DoorState};

#[test]
fn test_initial_state() {
    let d = Door::new();
    assert_eq!(d.state(), DoorState::Closed);
}

#[test]
fn test_open_from_closed() {
    let mut d = Door::new();
    assert!(d.open().is_ok());
    assert_eq!(d.state(), DoorState::Open);
}

#[test]
fn test_close_from_open() {
    let mut d = Door::new();
    d.open().unwrap();
    assert!(d.close().is_ok());
    assert_eq!(d.state(), DoorState::Closed);
}

#[test]
fn test_lock_unlock() {
    let mut d = Door::new();
    assert!(d.lock(1234).is_ok());
    assert_eq!(d.state(), DoorState::Locked);
    assert!(d.unlock(1234).is_ok());
    assert_eq!(d.state(), DoorState::Closed);
}

#[test]
fn test_invalid_transitions() {
    let mut d = Door::new();
    // Can't open a locked door
    d.lock(0000).unwrap();
    assert!(d.open().is_err());
    // Can't lock an open door
    let mut d2 = Door::new();
    d2.open().unwrap();
    assert!(d2.lock(9999).is_err());
}

