Implement Door state machine in src/lib.rs.

#[derive(Debug, PartialEq, Clone)]
pub enum DoorState {
    Open,
    Closed,
    Locked,
}

pub struct Door {
    state: DoorState,
    code: u32,
}

impl Door {
    pub fn new() -> Self {
        Door { state: DoorState::Closed, code: 0 }
    }

    pub fn state(&self) -> DoorState {
        self.state.clone()
    }

    pub fn open(&mut self) -> Result<(), &'static str> {
        match self.state {
            DoorState::Closed => { self.state = DoorState::Open; Ok(()) }
            _ => Err("can only open a closed door"),
        }
    }

    pub fn close(&mut self) -> Result<(), &'static str> {
        match self.state {
            DoorState::Open => { self.state = DoorState::Closed; Ok(()) }
            _ => Err("can only close an open door"),
        }
    }

    pub fn lock(&mut self, code: u32) -> Result<(), &'static str> {
        match self.state {
            DoorState::Closed => { self.code = code; self.state = DoorState::Locked; Ok(()) }
            _ => Err("can only lock a closed door"),
        }
    }

    pub fn unlock(&mut self, code: u32) -> Result<(), &'static str> {
        match self.state {
            DoorState::Locked if code == self.code => { self.state = DoorState::Closed; Ok(()) }
            DoorState::Locked => Err("wrong code"),
            _ => Err("door is not locked"),
        }
    }
}

